window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-137bbec2e1ed9a0b"]={"versions": [{"id": "FIG-137bbec2e1ed9a0b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints innerhalb der AUTOSAR Timing Extensions (Metamodell-Ausschnitt für VFB-Timing). Es definiert die Metaklasse <code>AgeConstraint</code> und deren semantische Verankerung an VFB-Ereignisse sowie Zeitmodelle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>AgeConstraint</code>: Zentrale Metaklasse, erbt via Generalisierung von <code>TimingConstraint::TimingConstraint</code> (spezialisiert <code>Identifiable</code>, <code>Traceable</code>).\n</li><li><code>TDEventVfb::TDEventVariableDataPrototype</code> (Paket <code>TDEventVfb</code>): Ziel der gerichteten Assoziation <code>+scope</code> mit Multiplizität <code>1</code>.\n</li><li><code>MultidimensionalTime::MultidimensionalTime</code> (Paket <code>MultidimensionalTime</code>): Über zwei Kompositionen angebunden:\n<ul class=\"fig-list\"><li><code>+minimum</code> mit Multiplizität <code>0..1</code>\n</li><li><code>+maximum</code> mit Multiplizität <code>0..1</code>\n Enthält die Attribute:\n</li><li><code>+ cseCode: CseCodeType</code>\n</li><li><code>+ cseCodeFactor: Integer</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Verhaltenssemantik. Ein <code>AgeConstraint</code> beschreibt eine Altersschranke für ein konkretes Variablen-Datenprototyp-Ereignis (<code>scope</code>), indem es das minimale (<code>minimum</code>) und/oder maximale (<code>maximum</code>) zulässige Alter über multidimensionale Zeitangaben quantifiziert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Ein <code>AgeConstraint</code> muss zwingend genau ein <code>TDEventVariableDataPrototype</code> über die Assoziation <code>scope</code> referenzieren (Kardinalität <code>1</code>). Die Begrenzungen für minimales und maximales Alter sind jeweils optional (<code>0..1</code>), jedoch typischerweise komplementär zu spezifizieren. Multi-dimensionale Zeitangaben nutzen <code>cseCode</code> und <code>cseCodeFactor</code>.</p>"}, {"id": "FIG-ce3b66121f6d6a05", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints innerhalb der AUTOSAR Timing Extensions. Es zeigt die Metaklasse <code>AgeConstraint</code> im generalisierten Kontext generischer Timing-Ereignisse und multidimensionaler Zeitstrukturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>AgeConstraint</code>: Metaklasse, erbt von <code>TimingConstraint::TimingConstraint</code> (mit den Vorfahren <code>Identifiable</code>, <code>Traceable</code>).\n</li><li><code>TimingDescription::TimingDescriptionEvent</code> (Paket <code>TimingDescription</code>): Ziel der gerichteten Assoziation <code>+scope</code> mit Multiplizität <code>0..1</code>.\n</li><li><code>MultidimensionalTime::MultidimensionalTime</code> (Paket <code>MultidimensionalTime</code>): Über zwei Kompositionen eingebunden:\n<ul class=\"fig-list\"><li><code>+minimum</code> (Multiplizität <code>0..1</code>)\n</li><li><code>+maximum</code> (Multiplizität <code>0..1</code>)\n Attribute:\n</li><li><code>+ cseCode :CseCodeType</code>\n</li><li><code>+ cseCodeFactor :Integer</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ausführungssemantik. Ein <code>AgeConstraint</code> schränkt das Alter eines Zeitereignisses ein, indem es relationale Grenzwerte für Mindest- (<code>minimum</code>) und Höchstalter (<code>maximum</code>) auf Basis multidimensionaler Zeitmodelle definiert. Die Referenzierung eines konkreten Ereignisses erfolgt über <code>scope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Bindung an ein Ereignis über <code>+scope</code> ist optional (<code>0..1</code>). Das referenzierte Ereignis ist auf die allgemeinere Ebene <code>TimingDescriptionEvent</code> abstrahiert. Die Zeitgrenzen <code>minimum</code> und <code>maximum</code> besitzen jeweils Multiplizität <code>0..1</code>. Attribute <code>cseCode</code> und <code>cseCodeFactor</code> definieren die Zeitbasis.</p>"}, {"id": "FIG-bdaac255288e0cb5", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints innerhalb der AUTOSAR Timing Extensions. Es zeigt die Metaklasse <code>AgeConstraint</code> im generalisierten Kontext generischer Timing-Ereignisse und multidimensionaler Zeitstrukturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>AgeConstraint</code>: Metaklasse, erbt von <code>TimingConstraint::TimingConstraint</code> (mit den Vorfahren <code>Identifiable</code>, <code>Traceable</code>).\n</li><li><code>TimingDescription::TimingDescriptionEvent</code> (Paket <code>TimingDescription</code>): Ziel der gerichteten Assoziation <code>+scope</code> mit Multiplizität <code>0..1</code>.\n</li><li><code>MultidimensionalTime::MultidimensionalTime</code> (Paket <code>MultidimensionalTime</code>): Über zwei Kompositionen eingebunden:\n<ul class=\"fig-list\"><li><code>+minimum</code> (Multiplizität <code>0..1</code>)\n</li><li><code>+maximum</code> (Multiplizität <code>0..1</code>)\n Attribute:\n</li><li><code>+ cseCode :CseCodeType</code>\n</li><li><code>+ cseCodeFactor :Integer</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ausführungssemantik. Ein <code>AgeConstraint</code> schränkt das Alter eines Zeitereignisses ein, indem es relationale Grenzwerte für Mindest- (<code>minimum</code>) und Höchstalter (<code>maximum</code>) auf Basis multidimensionaler Zeitmodelle definiert. Die Referenzierung eines konkreten Ereignisses erfolgt über <code>scope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Bindung an ein Ereignis über <code>+scope</code> ist optional (<code>0..1</code>). Das referenzierte Ereignis ist auf die allgemeinere Ebene <code>TimingDescriptionEvent</code> abstrahiert. Die Zeitgrenzen <code>minimum</code> und <code>maximum</code> besitzen jeweils Multiplizität <code>0..1</code>. Attribute <code>cseCode</code> und <code>cseCodeFactor</code> definieren die Zeitbasis.</p>"}, {"id": "FIG-ac039948b4dffd40", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints innerhalb der AUTOSAR Timing Extensions. Es zeigt die Metaklasse <code>AgeConstraint</code> im generalisierten Kontext generischer Timing-Ereignisse und multidimensionaler Zeitstrukturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>AgeConstraint</code>: Metaklasse, erbt von <code>TimingConstraint::TimingConstraint</code> (mit den Vorfahren <code>Identifiable</code>, <code>Traceable</code>).\n</li><li><code>TimingDescription::TimingDescriptionEvent</code> (Paket <code>TimingDescription</code>): Ziel der gerichteten Assoziation <code>+scope</code> mit Multiplizität <code>0..1</code>.\n</li><li><code>MultidimensionalTime::MultidimensionalTime</code> (Paket <code>MultidimensionalTime</code>): Über zwei Kompositionen eingebunden:\n<ul class=\"fig-list\"><li><code>+minimum</code> (Multiplizität <code>0..1</code>)\n</li><li><code>+maximum</code> (Multiplizität <code>0..1</code>)\n Attribute:\n</li><li><code>+ cseCode :CseCodeType</code>\n</li><li><code>+ cseCodeFactor :Integer</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ausführungssemantik. Ein <code>AgeConstraint</code> schränkt das Alter eines Zeitereignisses ein, indem es relationale Grenzwerte für Mindest- (<code>minimum</code>) und Höchstalter (<code>maximum</code>) auf Basis multidimensionaler Zeitmodelle definiert. Die Referenzierung eines konkreten Ereignisses erfolgt über <code>scope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Bindung an ein Ereignis über <code>+scope</code> ist optional (<code>0..1</code>). Das referenzierte Ereignis ist auf die allgemeinere Ebene <code>TimingDescriptionEvent</code> abstrahiert. Die Zeitgrenzen <code>minimum</code> und <code>maximum</code> besitzen jeweils Multiplizität <code>0..1</code>. Attribute <code>cseCode</code> und <code>cseCodeFactor</code> definieren die Zeitbasis.</p>"}, {"id": "FIG-79a0dff213717807", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints innerhalb der AUTOSAR Timing Extensions. Es zeigt die Metaklasse <code>AgeConstraint</code> im generalisierten Kontext generischer Timing-Ereignisse und multidimensionaler Zeitstrukturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>AgeConstraint</code>: Metaklasse, erbt von <code>TimingConstraint::TimingConstraint</code> (mit den Vorfahren <code>Identifiable</code>, <code>Traceable</code>).\n</li><li><code>TimingDescription::TimingDescriptionEvent</code> (Paket <code>TimingDescription</code>): Ziel der gerichteten Assoziation <code>+scope</code> mit Multiplizität <code>0..1</code>.\n</li><li><code>MultidimensionalTime::MultidimensionalTime</code> (Paket <code>MultidimensionalTime</code>): Über zwei Kompositionen angebunden:\n<ul class=\"fig-list\"><li><code>+minimum</code> (Multiplizität <code>0..1</code>)\n</li><li><code>+maximum</code> (Multiplizität <code>0..1</code>)\n Attribute:\n</li><li><code>+ cseCode: CseCodeType</code>\n</li><li><code>+ cseCodeFactor: Integer</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ausführungssemantik. Ein <code>AgeConstraint</code> schränkt das Alter eines Zeitereignisses ein, indem es relationale Grenzwerte für Mindest- (<code>minimum</code>) und Höchstalter (<code>maximum</code>) auf Basis multidimensionaler Zeitmodelle definiert. Die Referenzierung eines konkreten Ereignisses erfolgt über <code>scope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Bindung an ein Ereignis über <code>+scope</code> ist optional (<code>0..1</code>). Das referenzierte Ereignis ist auf die allgemeinere Ebene <code>TimingDescriptionEvent</code> abstrahiert. Die Zeitgrenzen <code>minimum</code> und <code>maximum</code> besitzen jeweils Multiplizität <code>0..1</code>. Attribute <code>cseCode</code> und <code>cseCodeFactor</code> definieren die Zeitbasis.</p>"}, {"id": "FIG-b7885cfd1ea274bd", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints innerhalb der AUTOSAR Timing Extensions. Es zeigt die Metaklasse <code>AgeConstraint</code> im generalisierten Kontext generischer Timing-Ereignisse und multidimensionaler Zeitstrukturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>AgeConstraint</code>: Metaklasse, erbt von <code>TimingConstraint</code> (mit den Vorfahren <code>Identifiable</code>, <code>Traceable</code>).\n</li><li><code>TimingDescriptionEvent</code> (Kontext <code>TimingDescription</code>): Ziel der gerichteten Assoziation <code>+scope</code> mit Multiplizität <code>0..1</code>.\n</li><li><code>MultidimensionalTime</code>: Über zwei Kompositionen angebunden:\n<ul class=\"fig-list\"><li><code>+minimum</code> (Multiplizität <code>0..1</code>)\n</li><li><code>+maximum</code> (Multiplizität <code>0..1</code>)\n Attribute mit expliziten Kardinalitäten:\n</li><li><code>+ cseCode: CseCodeType [0..1]</code>\n</li><li><code>+ cseCodeFactor: Integer [0..1]</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ausführungssemantik. Ein <code>AgeConstraint</code> schränkt das Alter eines Zeitereignisses ein, indem es relationale Grenzwerte für Mindest- (<code>minimum</code>) und Höchstalter (<code>maximum</code>) auf Basis multidimensionaler Zeitmodelle definiert. Die Referenzierung eines konkreten Ereignisses erfolgt über <code>scope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Assoziation <code>+scope</code> zu <code>TimingDescriptionEvent</code> ist optional (<code>0..1</code>). Die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> in <code>MultidimensionalTime</code> sind explizit als optional deklariert (<code>[0..1]</code>). Mindest- und Höchstaltersgrenzen (<code>minimum</code>, <code>maximum</code>) verbleiben bei <code>0..1</code>.</p>"}, {"id": "FIG-bc4501964258c33c", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints innerhalb der AUTOSAR Timing Extensions in kompakter Klassen- und Stereotypdarstellung. Es definiert <code>AgeConstraint</code> als spezialisiertes <code>TimingConstraint</code> in Relation zu <code>TimingDescriptionEvent</code> und <code>MultidimensionalTime</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>AgeConstraint</code>: Metaklasse mit dem Klassentyp/Supertyp <code>TimingConstraint</code> im Kopfbereich.\n</li><li><code>TimingDescriptionEvent</code> (Kontext <code>TimingDescription</code>): Ziel der gerichteten Assoziation <code>+scope</code> mit Multiplizität <code>0..1</code>.\n</li><li><code>MultidimensionalTime</code>: Über zwei Kompositionen angebunden:\n<ul class=\"fig-list\"><li><code>+minimum</code> (Multiplizität <code>0..1</code>)\n</li><li><code>+maximum</code> (Multiplizität <code>0..1</code>)\n Attribute:\n</li><li><code>+ cseCode: CseCodeType [0..1]</code>\n</li><li><code>+ cseCodeFactor: Integer [0..1]</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ausführungssemantik. Ein <code>AgeConstraint</code> schränkt das Alter eines Zeitereignisses ein, indem es relationale Grenzwerte für Mindest- (<code>minimum</code>) und Höchstalter (<code>maximum</code>) auf Basis multidimensionaler Zeitmodelle definiert. Die Referenzierung eines konkreten Ereignisses erfolgt über <code>scope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>AgeConstraint</code> ist als <code>TimingConstraint</code> klassifiziert. Die Assoziation <code>+scope</code> erlaubt die optionale Referenzierung eines <code>TimingDescriptionEvent</code> (<code>0..1</code>). Mindest- und Höchstaltersvorgaben werden über optionale Kompositionen (<code>0..1</code>) zu <code>MultidimensionalTime</code> ausgedrückt, deren Zeitbasis-Parameter <code>cseCode</code> und <code>cseCodeFactor</code> jeweils die Multiplizität <code>[0..1]</code> aufweisen.</p>"}, {"id": "FIG-5132e5ad2edddac7", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints innerhalb der AUTOSAR Timing Extensions in kompakter Klassen- und Stereotypdarstellung. Es definiert <code>AgeConstraint</code> als spezialisiertes <code>TimingConstraint</code> in Relation zu <code>TimingDescriptionEvent</code> und <code>MultidimensionalTime</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>AgeConstraint</code>: Metaklasse mit dem Klassentyp/Supertyp <code>TimingConstraint</code> im Kopfbereich.\n</li><li><code>TimingDescriptionEvent</code> (Kontext <code>TimingDescription</code>): Ziel der gerichteten Assoziation <code>+scope</code> mit Multiplizität <code>0..1</code>.\n</li><li><code>MultidimensionalTime</code>: Über zwei Kompositionen angebunden:\n<ul class=\"fig-list\"><li><code>+minimum</code> (Multiplizität <code>0..1</code>)\n</li><li><code>+maximum</code> (Multiplizität <code>0..1</code>)\n Attribute:\n</li><li><code>+ cseCode: CseCodeType [0..1]</code>\n</li><li><code>+ cseCodeFactor: Integer [0..1]</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ausführungssemantik. Ein <code>AgeConstraint</code> schränkt das Alter eines Zeitereignisses ein, indem es relationale Grenzwerte für Mindest- (<code>minimum</code>) und Höchstalter (<code>maximum</code>) auf Basis multidimensionaler Zeitmodelle definiert. Die Referenzierung eines konkreten Ereignisses erfolgt über <code>scope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>AgeConstraint</code> ist als <code>TimingConstraint</code> klassifiziert. Die Assoziation <code>+scope</code> erlaubt die optionale Referenzierung eines <code>TimingDescriptionEvent</code> (<code>0..1</code>). Mindest- und Höchstaltersvorgaben werden über optionale Kompositionen (<code>0..1</code>) zu <code>MultidimensionalTime</code> ausgedrückt, deren Zeitbasis-Parameter <code>cseCode</code> und <code>cseCodeFactor</code> jeweils die Multiplizität <code>[0..1]</code> aufweisen.</p>"}, {"id": "FIG-58a8c29cfe7b3db3", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von Timing-Constraints innerhalb der AUTOSAR Timing Extensions in kompakter Klassen- und Stereotypdarstellung. Es definiert <code>AgeConstraint</code> als spezialisiertes <code>TimingConstraint</code> in Relation zu <code>TimingDescriptionEvent</code> und <code>MultidimensionalTime</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>AgeConstraint</code>: Metaklasse mit dem Klassentyp/Supertyp <code>TimingConstraint</code> im Kopfbereich.\n</li><li><code>TimingDescriptionEvent</code> (Kontext <code>TimingDescription</code>): Ziel der gerichteten Assoziation <code>+scope</code> mit Multiplizität <code>0..1</code>.\n</li><li><code>MultidimensionalTime</code>: Über zwei Kompositionen angebunden:\n<ul class=\"fig-list\"><li><code>+minimum</code> (Multiplizität <code>0..1</code>)\n</li><li><code>+maximum</code> (Multiplizität <code>0..1</code>)\n Attribute:\n</li><li><code>+ cseCode: CseCodeType [0..1]</code>\n</li><li><code>+ cseCodeFactor: Integer [0..1]</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ausführungssemantik. Ein <code>AgeConstraint</code> schränkt das Alter eines Zeitereignisses ein, indem es relationale Grenzwerte für Mindest- (<code>minimum</code>) und Höchstalter (<code>maximum</code>) auf Basis multidimensionaler Zeitmodelle definiert. Die Referenzierung eines konkreten Ereignisses erfolgt über <code>scope</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\"><code>AgeConstraint</code> ist als <code>TimingConstraint</code> klassifiziert. Die Assoziation <code>+scope</code> erlaubt die optionale Referenzierung eines <code>TimingDescriptionEvent</code> (<code>0..1</code>). Mindest- und Höchstaltersvorgaben werden über optionale Kompositionen (<code>0..1</code>) zu <code>MultidimensionalTime</code> ausgedrückt, deren Zeitbasis-Parameter <code>cseCode</code> und <code>cseCodeFactor</code> jeweils die Multiplizität <code>[0..1]</code> aufweisen.</p>"}], "trans": [{"from": "FIG-137bbec2e1ed9a0b", "to": "FIG-ce3b66121f6d6a05", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Assoziation <code>+scope</code>: Zielklasse von <code>TDEventVfb::TDEventVariableDataPrototype</code> zu <code>TimingDescription::TimingDescriptionEvent</code> geändert.\n</li><li>Assoziation <code>+scope</code>: Multiplizität am Ziel von <code>1</code> auf <code>0..1</code> gelockert.\n</li><li>Farbgebung: Hintergrundfarbe der Modellelemente von Gelb auf Creme/Beige angepasst.\n</li></ul>"}, {"from": "FIG-ce3b66121f6d6a05", "to": "FIG-bdaac255288e0cb5", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bdaac255288e0cb5", "to": "FIG-ac039948b4dffd40", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ac039948b4dffd40", "to": "FIG-79a0dff213717807", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Klasse <code>MultidimensionalTime</code>: Formatierung der Attribute <code>cseCode</code> und <code>cseCodeFactor</code> vereinheitlicht (überflüssige Leerzeichen vor dem Doppelpunkt entfernt).\n</li></ul>"}, {"from": "FIG-79a0dff213717807", "to": "FIG-b7885cfd1ea274bd", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>MultidimensionalTime</code>: Multiplizitäten <code>[0..1]</code> für die Attribute <code>cseCode: CseCodeType</code> und <code>cseCodeFactor: Integer</code> explizit ergänzt.\n</li><li>Redaktionell: Paketpräfixe in Klassenköpfen (<code>TimingConstraint::</code>, <code>TimingDescription::</code>, <code>MultidimensionalTime::</code>) entfernt.\n</li></ul>"}, {"from": "FIG-b7885cfd1ea274bd", "to": "FIG-bc4501964258c33c", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Generalisierungshierarchie: Die separate Basisklasse <code>TimingConstraint</code> (inklusive Vorfahren <code>Identifiable</code> und <code>Traceable</code>) wurde als Kasten entfernt; stattdessen ist <code>TimingConstraint</code> kursiv in der Kopfzeile von <code>AgeConstraint</code> als Supertyp bzw. Stereotyp/Kontext annotiert.\n</li><li>Layout: Vertikal kompaktere Darstellung durch Wegfall des oberen Vererbungskastens.\n</li></ul>"}, {"from": "FIG-bc4501964258c33c", "to": "FIG-5132e5ad2edddac7", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5132e5ad2edddac7", "to": "FIG-58a8c29cfe7b3db3", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
